            results.reserve(specs.size());
            for (const auto& spec : specs) {
                results.push_back(loam::run_case(spec));
            }
            loam::write_report(argv[3], results);
            return 0;
        }
        if (argc == 4 && std::string(argv[1]) == "ingest") {
            return run_ingest(argv[2], argv[3]);
