use crate::model::{FoldErr, Mark, RUNE_FIXED, RUNE_VOID};

fn is_live(present: u8, origin: u8) -> bool {
    if origin == RUNE_VOID {
        return false;
    }
    if origin == RUNE_FIXED {
        return true;
    }
    present != 0
}

pub(crate) fn tilt_a(a: &[i64], b: &[u8], c: &[u8]) -> Result<Mark, FoldErr> {
    if a.is_empty() {
        return Err(FoldErr::Empty);
    }
    if a.len() != b.len() || a.len() != c.len() {
        return Err(FoldErr::Shape);
    }

    let mut low = 0;
    let mut high = 0;
    let mut saw_live = false;
    let mut has_absent = false;

    for ((value, present), origin) in a.iter().zip(b.iter()).zip(c.iter()) {
        if is_live(*present, *origin) {
            if saw_live {
                low = low.min(*value);
                high = high.max(*value);
            } else {
                low = *value;
                high = *value;
                saw_live = true;
            }
        } else {
            has_absent = true;
        }
    }

    if !saw_live {
        has_absent = true;
    }

    Ok(Mark {
        low,
        high,
        has_absent,
    })
}
